?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Manage Borrowings | BookNest</title><link rel="stylesheet" href="style.css"></head><body class="app-body"><header class="topbar"><a class="top-brand" href="dashboard.php">📚 BookNest <small>Library</small></a><div class="user-chip">🛡️ <?=htmlspecialchars($_SESSION['name'])?><span class="role-pill">Admin</span></div></header><main class="page-content"><div class="page-head"><div><div class="eyebrow">ADMIN CONTROL</div><h1>🔄 Manage Borrowings</h1><p>Monitor all student and faculty loans, due dates and returns.</p></div><div class="head-actions"><a class="secondary-btn" href="dashboard.php">🏠 Dashboard</a></div></div><div class="table-card"><div class="table-wrap"><table><thead><tr><th>Member</th><th>Role</th><th>ID</th><th>Book</th><th>Issued</th><th>Due Date</th><th>Returned</th><th>Status</th></tr></thead><tbody><?php if($result->num_rows===0): ?><tr><td colspan="8" class="empty">No borrowing records yet.</td></tr><?php else: while($r=$result->fetch_assoc()): $overdue=$r['status']==='issued' && $r['due_date'] && strtotime($r['due_date'])<time(); ?><tr><td><strong><?=htmlspecialchars($r['full_name'])?></strong></td><td><?=ucfirst(htmlspecialchars($r['role']))?></td><td><?=htmlspecialchars($r['roll_no'])?></td><td><?=htmlspecialchars($r['book_name'])?></td><td><?=date('d M Y',strtotime($r['issued_at']))?></td><td><?= $r['due_date'] ? date('d M Y',strtotime($r['due_date'])) : '—' ?><?php if($overdue): ?> <span class="overdue-tag">Overdue</span><?php endif; ?></td><td><?=$r['returned_at']?date('d M Y',strtotime($r['returned_at'])):'—'?></td><td><span class="status-<?=htmlspecialchars($r['status'])?>"><?=ucfirst($r['status'])?></span></td></tr><?php endwhile; endif; ?></tbody></table></div></div></main></body></html>
